#!/usr/bin/env bash
# ==============================================================================
# scripts/sync-orchestrator-secret.sh
# Copies the orchestrator's Keycloak client secret (generated by Keycloak, kept only in local Terraform state) into the
# cluster as the 'orchestrator-oidc' Secret, then restarts the orchestrator. Run after
# `terraform -chdir=terraform/identity/keycloak apply`.
# ==============================================================================
set -euo pipefail

ROOT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"

SECRET="$(terraform -chdir="${ROOT_DIR}/terraform/identity/keycloak" output -raw orchestrator_client_secret)"
if [ -z "$SECRET" ]; then
  echo "ERROR: no orchestrator_client_secret in the Keycloak Terraform outputs. Apply terraform/identity/keycloak first." >&2
  exit 1
fi

kubectl create secret generic orchestrator-oidc -n agent-system \
  --from-literal=ORCHESTRATOR_CLIENT_SECRET="$SECRET" \
  --dry-run=client -o yaml | kubectl apply -f -
kubectl -n agent-system rollout restart deployment/agent-orchestrator
echo "orchestrator-oidc Secret updated and the orchestrator restarted."
